process fx05_spin(at: location, steps: number) {
    t0 = value.server_current_tick
    a = 0
    repeat steps {
        a = wrap(a + 12, 0, 360)
        @all display_particle_circle(particle(end_rod), at, 1.5, 3, a, vec(0, 1, 0))
        wait(2)
    }
    t1 = value.server_current_tick
    @all send_message("fx05 тиков=${t1 - t0} угол=${a}")
}

when player_chat {
    if not chat_message_equals("@fx05") {
        end_thread()
    }
    cancel_event()
    start fx05_spin(value.location, 30, target_mode: no_target)
    send_message("fx05 событие свободно")
}

game fx06_aura: list
game fx06_frames
game fx06_mark

process fx06_loop() {
    forever {
        wait(4)
        for name in fx06_aura {
            player_by_name(name)
            at = @current value.location
            @all display_particle_circle(particle(witch), at, 0.8, 4, 0, vec(0, 1, 0))
            fx06_frames += 1
        }
        reset()
    }
}

when world_start {
    fx06_aura = []
    fx06_frames = 0
    start fx06_loop(target_mode: no_target)
}

when player_chat {
    if not chat_message_equals("@fx06") {
        end_thread()
    }
    cancel_event()
    if value.name in fx06_aura {
        fx06_aura = remove_list_value(fx06_aura, value.name, remove_mode: all)
        fx06_mark = fx06_frames
        send_message("fx06 выкл кадров=${fx06_frames}")
    } else {
        fx06_aura = append_value(value.name)
        send_message("fx06 вкл")
    }
}

when player_chat {
