process fx11_type(line: text) {
    n = text_length(line)
    for i in 1..n {
        part = trim_text(line, 0, i)
        send_action_bar("&6${part}")
        wait(1)
    }
    send_message("fx11 напечатано")
}

func fx11_bar(now: number, total: number) {
    full = round(now / total * 20)
    done = repeat_text("█", full)
    left = repeat_text("█", 20 - full)
    send_action_bar("&a${done}&8${left}")
    send_message("fx11 полных=${full}")
}

when player_chat {
    if chat_message_equals("@fx11") {
        cancel_event()
        start fx11_type("fx11 Привет, мир")
    }
    if chat_message_equals("@fx11b") {
        cancel_event()
        fx11_bar(7, 10)
    }
}

const FX12_BOSS = "fx12_boss"

when entity_take_damage {
    if not @victim entity.name_equals(FX12_BOSS) {
        end_thread()
    }
    now = value.current_health - value.event_final_damage
    total = value.max_health
    if now > 0 {
        @all set_boss_bar("fx12", "&cfx12 Страж &f${round(now)}", now / total * 100, style: notched_10, color: red, sky_effect: dark_sky)
    }
}

when entity_death {
    if entity.name_equals(FX12_BOSS) {
        @all remove_boss_bar("fx12")
        @all send_message("fx12 босс убит")
    }
}

